import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { transform } from 'sucrase';
import { grammarDir, runTreeSitter } from './tree-sitter';

const sourcePath = join(grammarDir, 'grammar.ts');
const outputPath = join(grammarDir, 'grammar.js');
const header = '// Generated by scripts/generate-grammar.ts from grammar.ts. Do not edit.\n\n';

export function renderGrammarJs(): string {
  const source = readFileSync(sourcePath, 'utf8').replaceAll('\r\n', '\n');
  const withoutReference = source.replace(/^\/\/\/ <reference .*\/>\n\n?/, '');
  const javascript = transform(withoutReference, { transforms: ['typescript'] }).code;
  return `${header}${javascript.replace(/\s*$/, '\n')}`;
}

export function checkGrammarJs(): boolean {
  const expected = renderGrammarJs();
  const actual = readFileSync(outputPath, 'utf8').replaceAll('\r\n', '\n');
  if (expected === actual) {
    return true;
  }

  console.error('grammar.js is stale. Run `bun run generate` and commit grammar.js.');
  return false;
}

export function writeGrammarJs(): void {
  writeFileSync(outputPath, renderGrammarJs());
}

export function generateParser(): boolean {
  const result = runTreeSitter(['generate', '--abi', '15', '--js-runtime', 'bun']);
  if (result.status !== 0) {
    console.error(result.stderr || result.stdout);
    return false;
  }
  return true;
}
